css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-flip{width:min(980px,100%)}
.fx-flip .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.5em;perspective:1200px}
.fx-flip .flip{all:unset;display:block;cursor:pointer;aspect-ratio:4/5;position:relative;border-radius:var(--radius);text-align:left;box-sizing:border-box}
.fx-flip .flip:focus-visible{outline:2px solid var(--accent);outline-offset:4px}
.fx-flip .in{position:absolute;inset:0;transform-style:preserve-3d;transition:transform calc(.8s/var(--speed)) cubic-bezier(.3,.8,.2,1)}
.fx-flip .flip.on .in{transform:rotateY(180deg)}
@media(hover:hover){.fx-flip .flip:hover .in{transform:rotateY(180deg)}}
.fx-flip .f,.fx-flip .bk{position:absolute;inset:0;border-radius:var(--radius);overflow:hidden;-webkit-backface-visibility:hidden;backface-visibility:hidden}
.fx-flip .f{border:1px solid var(--border);background:color-mix(in srgb,var(--surface) 94%,var(--text));display:flex;flex-direction:column}
.fx-flip .f .fx-art{flex:1}
.fx-flip .f .cap{padding:1em 1.2em 1.1em;display:block}.fx-flip .f small{display:block;font-size:.72em;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--accent)}
.fx-flip .f b{display:block;font:600 1.3em var(--font-heading);margin-top:.2em}
.fx-flip .bk{transform:rotateY(180deg);display:flex;flex-direction:column;justify-content:space-between;padding:1.5em 1.4em;background:var(--primary);color:var(--on-primary)}
.fx-flip .bk b{display:block;font:600 1.4em var(--font-heading)}.fx-flip .bk span{display:block;opacity:.85;font-size:.95em;margin-top:.6em}
.fx-flip .bk em{font-style:normal;font-weight:700;font-size:.85em;border-top:1px solid color-mix(in srgb,var(--on-primary) 35%,transparent);padding-top:.8em;display:block}
.fx-flip .flip:nth-child(2) .bk{background:var(--accent);color:var(--on-accent)}.fx-flip .flip:nth-child(2) .bk em{border-color:color-mix(in srgb,var(--on-accent) 35%,transparent)}
.fx-flip .flip:nth-child(3) .bk{background:color-mix(in srgb,var(--primary) 70%,#000)}
@media(max-width:760px){.fx-flip .grid{grid-template-columns:1fr;max-width:340px;margin:0 auto}.fx-flip .flip{aspect-ratio:4/3.4}}
@media(prefers-reduced-motion:reduce){.fx-flip .in{transition:none;transform:none!important}.fx-flip .f,.fx-flip .bk{-webkit-backface-visibility:visible;backface-visibility:visible;transition:opacity .3s}.fx-flip .bk{transform:none;opacity:0}.fx-flip .flip.on .bk{opacity:1}.fx-flip .flip.on .f{opacity:0}.fx-flip .flip:hover .bk{opacity:1}
.fx-flip .flip.is-tap .bk{opacity:1}}

/* touch: :hover mirrored as .is-tap */
.fx-flip .flip.is-tap .in{transform:rotateY(180deg)}
